        static string Display(string value){switch(value){case "Ready":return "准备抛竿";case "GoSpot":return "沿记录路线到钓点";case "WaitBite":return "等待水花";case "LootWait":return "等待自身拾取";case "RecastDelay":return "收获后等待";case "ReturnNpc":return "包满返商人";case "NpcScan":return "核对商人";case "VendorWait":return "等待插件清包";case "ReturnSpot":return "逆序返回钓点";case "RestoreFacing":return "恢复钓鱼朝向";case "Stopped":return "已停止";case "Countdown":return "倒计时";case "Holding":return "正在短按";case "WaitingForFrame":return "等待新数据";case "Faulted":return "输入故障";case "Completed":return "已完成";default:return value;}}
        static Label Label(string value){return new Label{Text=value,AutoSize=true,Margin=new Padding(7,7,4,0)};}
        static FlowLayoutPanel Row(){return new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,WrapContents=false,Margin=new Padding(0)};}
        static TableLayoutPanel Group(TableLayoutPanel root,string title,int index,int count){var g=new GroupBox{Text=title,Dock=DockStyle.Fill,Padding=new Padding(7),Margin=new Padding(0,3,0,5)};root.Controls.Add(g,0,index);var rows=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=count};for(int i=0;i<count;i++)rows.RowStyles.Add(new RowStyle(SizeType.Percent,100f/count));g.Controls.Add(rows);return rows;}
        static void Check(Control row,CheckBox box,string caption){box.Text=caption;box.AutoSize=true;box.Margin=new Padding(5,5,8,0);row.Controls.Add(box);}
        static Button Button(string text,Action action){var b=new Button{Text=text,AutoSize=true,MinimumSize=new Size(70,27),Margin=new Padding(3,0,3,0)};b.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(ex.Message,"本次操作未执行",MessageBoxButtons.OK,MessageBoxIcon.Information);}};return b;}
        static string UserDirectory(){string p=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"profiles","user","fishing");Directory.CreateDirectory(p);return p;}
        static string TemplateDirectory(){return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","fishing");}
        void Prepare(){if(prepare!=null)prepare();}
        void Record(string message){lock(eventGate){events.Add(DateTimeOffset.Now.ToString("o")+" "+message);if(events.Count>2000)events.RemoveAt(0);}if(parentLog!=null)try{parentLog(message);}catch{}}
        void ClearRun(){runClock.Reset();session=null;simulation=null;runPlan=null;lastObservation=null;lastReport="";lastState="";lastEvidence=0;stopHandled=false;if(journal!=null){journal.Dispose();journal=null;}lock(eventGate)events.Clear();}
        void ResetDemo(){StopWorkspace("恢复钓鱼演示");ClearRun();plan=new FishingSimulator().Plan.Clone();resumeCheckpoint=null;resume.Checked=false;Populate();state.Text="离线演示：两次收获 → 包满返商人 → 等待清包 → 原路返回，系统输入为 0。";}
        void Populate(){changing=true;cast.SelectedIndex=plan.Settings.CastKey-49;turn.SelectedIndex=plan.Movement.TurnLeft==0x25?2:plan.Movement.TurnLeft==0x41?1:0;select.SelectedIndex=plan.Settings.SelectKey==9?0:1;minimum.Value=plan.Settings.MinimumFreeSlots;vendor.Checked=plan.Settings.EnableVendor;noAudio.Checked=!plan.Settings.RequireAudio;npcName.Text=plan.Vendor==null?"":plan.Vendor.Name;bindings.Checked=autoLoot.Checked=audioConfirmed.Checked=autoSell.Checked=calibrated.Checked=false;changing=false;UpdateSummary();}
        FishingPlan ReadPlan(bool live){var p=plan.Clone();p.Settings.CastKey=(ushort)(49+cast.SelectedIndex);p.Settings.SelectKey=(ushort)(select.SelectedIndex==0?9:0x75);p.Settings.MinimumFreeSlots=(int)minimum.Value;p.Settings.EnableVendor=vendor.Checked;p.Settings.RequireAudio=!noAudio.Checked;p.Settings.BindingsConfirmed=live&&bindings.Checked;p.Settings.AutoLootConfirmed=live&&autoLoot.Checked;p.Settings.AudioConfirmed=live&&audioConfirmed.Checked;p.Settings.AutoSellConfirmed=live&&autoSell.Checked;p.Calibration.Confirmed=live&&calibrated.Checked;if(turn.SelectedIndex==2){p.Movement.TurnLeft=0x25;p.Movement.TurnRight=0x27;p.Movement.StrafeLeft=0x41;p.Movement.StrafeRight=0x44;}else if(turn.SelectedIndex==1){p.Movement.TurnLeft=0x41;p.Movement.TurnRight=0x44;p.Movement.StrafeLeft=0x51;p.Movement.StrafeRight=0x45;}else{p.Movement.TurnLeft=0x51;p.Movement.TurnRight=0x45;p.Movement.StrafeLeft=0x41;p.Movement.StrafeRight=0x44;}p.Validate();return p;}
        OperationObservation CurrentGame(){var o=gameReader==null?null:gameReader();return o==null?new OperationObservation():o.Clone();}
        OperationObservation ValidGame(){var o=CurrentGame();if(!o.Fresh||o.Farm==null||!o.Farm.Fresh||!o.Farm.KnownCore||!NavigationMath.InRange(o.Farm.X,0,1)||!NavigationMath.InRange(o.Farm.Y,0,1)||!NavigationMath.InRange(o.Farm.Facing,0,Math.PI*2))throw new InvalidOperationException("需要已定位、同步更新且坐标/朝向可读的状态面板。");return o;}
        void UpdateSummary(){summary.Text=String.Format("地图 {0} / {1}；钓点 ({2:F4}, {3:F4})；路线 {4} 点；NPC：{5}",plan.Calibration.MapId,plan.Calibration.Zone,plan.Spot.X,plan.Spot.Y,plan.VendorRoute==null?0:plan.VendorRoute.Points.Count,plan.Vendor==null?"未保存":plan.Vendor.Name);}
        void SaveSpot(){if(Busy)throw new InvalidOperationException("请先停止运行或结束录制。");var edited=ReadPlan(false);var o=ValidGame();edited.Spot=new Waypoint{X=o.Farm.X,Y=o.Farm.Y,Tolerance=.003};edited.Facing=o.Farm.Facing;edited.Calibration.MapId=o.Farm.MapId;edited.Calibration.MapMode=o.Farm.MapMode;edited.Calibration.Zone=o.Farm.Zone;edited.Calibration.Confirmed=false;edited.Settings.EnableVendor=false;edited.VendorRoute=null;plan=edited;ClearRun();Populate();Record("已保存当前钓点和朝向；旧返程路线已解除，需要重新录制或载入。");}
        void BeginRecording(){if(Busy)throw new InvalidOperationException("请先停止运行或已有录制。");var edited=ReadPlan(false);Prepare();var o=ValidGame();if(o.Farm.MapId!=edited.Calibration.MapId||o.Farm.MapMode!=edited.Calibration.MapMode||o.Farm.Zone!=edited.Calibration.Zone||NavigationMath.Distance(o.Farm.X-edited.Spot.X,o.Farm.Y-edited.Spot.Y,edited.Calibration.AxisScale)>edited.Spot.Tolerance)throw new InvalidOperationException("请先回到保存的钓点，再从钓点录制商人路线。");plan=edited;recording=new RouteDocument{RouteId=Guid.NewGuid().ToString("N"),Name="钓鱼返商人路线",RouteType="vendor_return",MapId=o.Farm.MapId,MapMode=o.Farm.MapMode,Zone=o.Farm.Zone,AllowReverse=true};isRecording=true;AddPoint();state.Text="正在录制；到拐点按 F7，抵达 NPC 后按 F8。";}
        void AddPoint(){if(!isRecording)throw new InvalidOperationException("请先开始录制。");var o=ValidGame();if(o.Farm.MapId!=recording.MapId||o.Farm.MapMode!=recording.MapMode||o.Farm.Zone!=recording.Zone)throw new InvalidOperationException("录制地图发生变化。");if(recording.Points.Count>=5000)throw new InvalidOperationException("路线点数已到上限。");if(recording.Points.Count>0){var last=recording.Points[recording.Points.Count-1];if(NavigationMath.Distance(o.Farm.X-last.X,o.Farm.Y-last.Y,plan.Calibration.AxisScale)<.0001)return;}recording.Points.Add(new Waypoint{X=o.Farm.X,Y=o.Farm.Y,Tolerance=.003});Record("已记录路点 "+recording.Points.Count);}
        void EndRecording(){if(!isRecording)throw new InvalidOperationException("没有正在录制的路线。");recording.Validate();plan.VendorRoute=recording.Clone();isRecording=false;recording=null;UpdateSummary();Record("路线已结束，可导出并保存 NPC。");}
        void SaveRoute(){if(isRecording)throw new InvalidOperationException("请先结束录制。");if(plan.VendorRoute==null)throw new InvalidOperationException("没有可导出的路线。");using(var d=new SaveFileDialog{Filter="商人路线 JSON|*.json",InitialDirectory=UserDirectory(),FileName="fishing-vendor.json"})if(d.ShowDialog()==DialogResult.OK)RouteStore.Save(d.FileName,plan.VendorRoute);}
        void LoadRoute(){if(Busy)throw new InvalidOperationException("请先停止运行或录制。");using(var d=new OpenFileDialog{Filter="商人路线 JSON|*.json",InitialDirectory=UserDirectory()})if(d.ShowDialog()==DialogResult.OK){var p=ReadPlan(false);var r=RouteStore.Load(d.FileName);if(r.RouteType!="vendor_return"||!r.AllowReverse||r.Loop||r.MapId!=p.Calibration.MapId||r.MapMode!=p.Calibration.MapMode||r.Zone!=p.Calibration.Zone||NavigationMath.Distance(r.Points[0].X-p.Spot.X,r.Points[0].Y-p.Spot.Y,p.Calibration.AxisScale)>p.Spot.Tolerance)throw new FormatException("需要从钓点开始、同图且可逆的商人路线。");p.VendorRoute=r;plan=p;ClearRun();Populate();Record("商人路线已载入，实机确认已清空。");}}
        void SaveNpc(){if(Busy)throw new InvalidOperationException("请先停止运行或录制。");var p=ReadPlan(false);var o=ValidGame();var f=o.Farm;string name=String.IsNullOrWhiteSpace(npcName.Text)?f.TargetName:npcName.Text.Trim();if(!f.TargetExists||!f.TargetIdentityKnown||f.TargetToken==0||!f.NameHashKnown||TargetCatalog.HashName(name)!=f.TargetNameHash||!f.AttackabilityKnown||f.TargetCanAttack||f.TargetIsPlayer||!f.TargetDeadKnown||f.TargetDead)throw new InvalidOperationException("请选择可核验的友方 NPC；名称超出面板长度时需先填完整名称并匹配哈希。");p.Vendor=new BattleTarget{Name=name,NameHash=f.TargetNameHash,Kind="npc"};plan=p;ClearRun();Populate();Record("已保存 NPC："+name);}
        void LoadCalibration(){if(Busy)throw new InvalidOperationException("请先停止运行或录制。");using(var d=new OpenFileDialog{Filter="地图标定 JSON|*.json",InitialDirectory=UserDirectory()})if(d.ShowDialog()==DialogResult.OK){if(new FileInfo(d.FileName).Length>65536)throw new FormatException("标定文件过大。");var c=new JavaScriptSerializer().Deserialize<NavigationCalibration>(File.ReadAllText(d.FileName,Encoding.UTF8));if(c==null)throw new FormatException("标定为空。");c.Validate();var p=ReadPlan(false);if(c.MapId!=p.Calibration.MapId||c.MapMode!=p.Calibration.MapMode||c.Zone!=p.Calibration.Zone)throw new FormatException("标定不属于钓点地图。");c.Confirmed=false;p.Calibration=c;plan=p;ClearRun();Populate();Record("标定已载入，需要重新人工确认。");}}
        void LoadPlan(){if(Busy)throw new InvalidOperationException("请先停止运行或录制。");using(var d=new OpenFileDialog{Filter="钓鱼方案 JSON|*.json",InitialDirectory=UserDirectory()})if(d.ShowDialog()==DialogResult.OK)LoadPlanFile(d.FileName);}
        void LoadPlanFile(string path){var p=FishingPlanStore.Load(path);StopWorkspace("载入钓鱼方案");ClearRun();plan=p;resumeCheckpoint=null;resume.Checked=false;Populate();state.Text="方案已载入，实机确认已清空，尚未启动。";}
        void SavePlan(){var p=ReadPlan(false);using(var d=new SaveFileDialog{Filter="钓鱼方案 JSON|*.json",InitialDirectory=UserDirectory(),FileName="fishing-plan.json"})if(d.ShowDialog()==DialogResult.OK)FishingPlanStore.Save(d.FileName,p);}
        void LoadCheckpoint(){if(Busy)throw new InvalidOperationException("请先停止钓鱼或录制。");var p=ReadPlan(false);using(var d=new OpenFileDialog{Filter="钓鱼断点 JSON|*.json",InitialDirectory=UserDirectory(),FileName="last-checkpoint.json"})if(d.ShowDialog()==DialogResult.OK){resumeCheckpoint=FishingCheckpointStore.Load(d.FileName,p);resume.Checked=false;state.Text="断点已读取："+resumeCheckpoint.Phase+" / 路点 "+resumeCheckpoint.RouteIndex+"。请先到对应记录点，再勾选恢复并启动。";}}
        void Inspect(){var p=ReadPlan(true);var o=ReadCached();string problem=FishingEngine.ValidateLiveObservation(p,o);var b=new StringBuilder("# 钓鱼启动条件\r\n\r\n");b.AppendLine("游戏验收：pending。检查不会输出按键。\r\n");b.AppendLine("- 当前观察："+(problem??"当前只读观察满足基本条件"));b.AppendLine("- 按键 / Auto Loot / 声音确认："+(p.Settings.BindingsConfirmed&&p.Settings.AutoLootConfirmed&&p.Settings.AudioConfirmed?"已勾选":"尚未全部确认"));b.AppendLine("- 返程标定 / 自动售卖确认："+(!p.Settings.EnableVendor||p.Calibration.Confirmed&&p.Settings.AutoSellConfirmed?"已满足或未启用":"尚未确认"));b.AppendLine("- 输入故障锁："+(safety.Faulted?safety.Reason:"未触发"));b.AppendLine("- F 实际收杆、模板误报率与连续游戏运行仍需现场核验。");new ReadinessReportForm("钓鱼启动条件",b.ToString()).Show(this);}
        void StartListening(){StopListening();sounds=new FishingSoundDetector(TemplateDirectory());text=new FishingBagTextDetector(TemplateDirectory());textOnset=-1;lastTextSeen=-100000;textScore=0;lastAudioError="";long epoch=System.Threading.Interlocked.Increment(ref audioEpoch);var activeDetector=sounds;audio=new WindowsFishingAudioCapture(delegate(float[] samples,int rate,long end,bool unreliable){if(System.Threading.Interlocked.Read(ref audioEpoch)!=epoch)return;var detector=activeDetector;if(detector==null)return;if(unreliable){System.Threading.Interlocked.Exchange(ref lastAudibleMs,-1);detector.Reset();lock(cacheGate){if(cached!=null){cached.AudioReady=false;cached.LastBiteAtMs=cached.LastBagVoiceAtMs=-1;cached.BiteConfidence=cached.BagVoiceConfidence=0;}}return;}double energy=0;foreach(float sample in samples)energy+=(double)sample*sample;if(samples.Length>0&&energy/samples.Length>1e-10)System.Threading.Interlocked.Exchange(ref lastAudibleMs,end);detector.Push(samples,rate,end);},()=>clock.ElapsedMilliseconds);audio.Start();Record("已请求系统播放环回监听；不采麦克风，不保存原始系统音频。");}
        void StopListening(){System.Threading.Interlocked.Increment(ref audioEpoch);System.Threading.Interlocked.Exchange(ref lastAudibleMs,-1);var a=audio;audio=null;if(a!=null)a.Dispose();var detector=sounds;if(detector!=null)detector.Reset();sounds=null;text=null;lock(cacheGate){if(cached!=null){cached.AudioReady=false;cached.LastBiteAtMs=cached.LastBagVoiceAtMs=cached.LastBagTextAtMs=-1;cached.BiteConfidence=cached.BagVoiceConfidence=cached.BagTextConfidence=0;}}}
        void StartLive(){if(resume.Checked&&resumeCheckpoint==null)throw new InvalidOperationException("请先读取并核对本方案断点。");if(isRecording)throw new InvalidOperationException("请先结束录制。");var p=ReadPlan(true);if(!p.Settings.BindingsConfirmed||!p.Settings.AutoLootConfirmed||!p.Settings.AudioConfirmed||!p.Calibration.Confirmed||(p.Settings.EnableVendor&&!p.Settings.AutoSellConfirmed))throw new InvalidOperationException("请完成实机前人工核对。");Prepare();StopWorkspace("准备钓鱼实机运行");ClearRun();try{StartListening();}catch{if(p.Settings.RequireAudio)throw;}pendingPlan=p;pendingUntil=clock.ElapsedMilliseconds+5000;state.Text="等待有效状态和声音（最多 5 秒），请切换到游戏；准备好后才开始 5 秒倒计时。";RefreshHotkeys();}
        void ArmPending(FishingObservation o){if(pendingPlan==null)return;long now=clock.ElapsedMilliseconds;if(now>=pendingUntil){pendingPlan=null;StopWorkspace("未等到有效游戏状态或声音，未启动。");return;}if(!o.Game.Fresh||pendingPlan.Settings.RequireAudio&&!o.AudioReady)return;var p=pendingPlan;pendingPlan=null;FishingSession candidate=null;try{string problem=FishingEngine.ValidateLiveObservation(p,o);if(problem!=null)throw new InvalidOperationException(problem);journal=new RunJournal(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"runtime","fishing"),false);var b=backendFactory==null?null:backendFactory();if(b==null)throw new InvalidOperationException("请先选择并定位游戏窗口。");candidate=new FishingSession(b,()=>clock.ElapsedMilliseconds,ReadCached,Record,safety);candidate.Start(p,resume.Checked?resumeCheckpoint:null,resume.Checked);runClock.Restart();session=candidate;runPlan=p.Clone();lastState="";Record("钓鱼会话进入5秒倒计时；game_validation仍为pending。");}catch(Exception ex){if(candidate!=null)candidate.Stop("钓鱼启动失败");session=null;runPlan=null;if(journal!=null){journal.Dispose();journal=null;}StopListening();state.Text="钓鱼未启动："+ex.Message;Record(state.Text);}RefreshHotkeys();}
        void StartSimulation(){if(isRecording)throw new InvalidOperationException("请先结束录制。");Prepare();StopWorkspace("启动钓鱼离线模拟");ClearRun();var p=ReadPlan(false);simulation=new FishingSimulator(p){NoBite=noBite.Checked,NoSale=noSale.Checked,WrongNpc=wrongNpc.Checked};runPlan=simulation.Plan.Clone();journal=new RunJournal(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"runtime","fishing"),true);runClock.Restart();simTimer.Start();RefreshHotkeys();}
        void Simulate(){try{for(int i=0;i<(int)speed.Value&&simulation!=null&&!simulation.Completed;i++){var c=simulation.Step();lastObservation=simulation.Observation.Clone();Evidence(simulation.Engine.Status,lastObservation,c,simulation.ElapsedMilliseconds);if(c.Action==FishingAction.Stop)break;}if(simulation.Completed||simulation.Engine.Status=="Stopped"){simTimer.Stop();runClock.Stop();}state.Text="离线模拟 · "+Display(simulation.Engine.Status)+"；计划抛竿 "+simulation.Engine.Casts+"，确认收获 "+simulation.Engine.ConfirmedCatches+"，商人往返 "+simulation.Engine.VendorVisits+"。输入 0，详细原因见记录，游戏待测。";}catch(Exception ex){simTimer.Stop();runClock.Stop();Record("模拟停止："+ex.Message);state.Text=ex.Message;}RefreshHotkeys();}
        FishingObservation ReadCached(){FishingObservation o;lock(cacheGate)o=cached==null?new FishingObservation():cached.Clone();if(sourceFresh!=null&&!sourceFresh()){o.Game.Fresh=false;if(o.Game.Farm!=null)o.Game.Farm.Fresh=false;}var a=audio;long now=clock.ElapsedMilliseconds,audible=System.Threading.Interlocked.Read(ref lastAudibleMs);if(a==null||!a.Running||a.LastPacketMs<0||now<a.LastPacketMs||now-a.LastPacketMs>=1500||!String.IsNullOrEmpty(a.Error)||audible<0||now<audible||now-audible>=5000){o.AudioReady=false;o.LastBiteAtMs=o.LastBagVoiceAtMs=-1;o.BiteConfidence=o.BagVoiceConfidence=0;}else{var detector=sounds;if(detector!=null){var current=detector.Snapshot();o.LastBiteAtMs=current.LastBiteAtMs;o.LastBagVoiceAtMs=current.LastBagVoiceAtMs;o.BiteConfidence=current.BiteConfidence;o.BagVoiceConfidence=current.BagVoiceConfidence;}}return o;}
        void Produce(){if(closing)return;try{long now=clock.ElapsedMilliseconds;var o=new FishingObservation{CapturedAtMs=now,Game=CurrentGame()};var a=audio;var detector=sounds;if(a!=null&&detector!=null){var s=detector.Snapshot();o.LastBiteAtMs=s.LastBiteAtMs;o.LastBagVoiceAtMs=s.LastBagVoiceAtMs;o.BiteConfidence=s.BiteConfidence;o.BagVoiceConfidence=s.BagVoiceConfidence;long audible=System.Threading.Interlocked.Read(ref lastAudibleMs);o.AudioReady=a.Running&&a.LastPacketMs>=0&&now>=a.LastPacketMs&&now-a.LastPacketMs<1500&&audible>=0&&now>=audible&&now-audible<5000&&String.IsNullOrEmpty(a.Error);if(!String.IsNullOrEmpty(a.Error)&&a.Error!=lastAudioError){lastAudioError=a.Error;Record("声音采集失效："+a.Error);}}
                if(text!=null&&gameCapture!=null&&o.Game.Fresh&&now-lastVisual>=200){lastVisual=now;try{using(var image=gameCapture())textScore=text.Score(image);if(textScore>=.80){if(now-lastTextSeen>500)textOnset=now;lastTextSeen=now;}}catch{textScore=0;}}
                if(now-lastTextSeen<=2000){o.LastBagTextAtMs=textOnset;o.BagTextConfidence=textScore;}lock(cacheGate)cached=o;
                if((Native.GetAsyncKeyState(0x7B)&0x8000)!=0&&(Native.GetAsyncKeyState(0x11)&0x8000)==0&&!hotkeyStart&&(Busy||audio!=null))StopWorkspace("F12 急停。");if(hotkeyStart&&(Native.GetAsyncKeyState(0x7B)&0x8000)==0&&(Native.GetAsyncKeyState(0x11)&0x8000)==0){hotkeyStart=false;StartLive();}else if(pendingPlan!=null&&(Native.GetAsyncKeyState(0x7B)&0x8000)!=0)StopWorkspace("F12 取消钓鱼准备。");ArmPending(o);
                var live=session;if(live!=null){lastObservation=o;var c=live.LastCommand;Evidence(live.EngineStatus,o,c,0);state.Text="实机 "+Display(live.Status)+" / "+Display(live.EngineStatus)+"；计划抛竿 "+live.Casts+"，确认收获 "+live.ConfirmedCatches+"。停止或异常原因见下方记录，可导出反馈。";if(!live.IsActive&&!stopHandled){lastSessionStop=clock.ElapsedMilliseconds;runClock.Stop();stopHandled=true;SaveCheckpoint();if(audio!=null)StopListening();RefreshHotkeys();}}
                signals.Text=String.Format("环回：{0}；上次水花匹配 {1:F2}；上次包满语音 {2:F2}；顶部字形 {3:F2}；识别结果均为候选。",o.AudioReady?"有新数据":"未就绪",o.BiteConfidence,o.BagVoiceConfidence,o.BagTextConfidence);string[] lines;lock(eventGate)lines=events.ToArray();output.Lines=lines;if(lines.Length>0){output.SelectionStart=output.TextLength;output.ScrollToCaret();}
            }catch(Exception ex){Record("钓鱼观察失败："+ex.Message);if(session!=null&&session.IsActive)session.Stop("钓鱼观察生产失败。");} }
        void Evidence(string status,FishingObservation o,FishingCommand c,long virtualMs){long now=clock.ElapsedMilliseconds;if(journal==null)return;if(status==lastState&&now-lastEvidence<250)return;lastEvidence=now;var details=new{reason=c==null?"":c.Reason,purpose=c==null?"":c.Purpose.ToString(),o.LastBiteAtMs,o.BiteConfidence,o.LastBagVoiceAtMs,o.BagVoiceConfidence,o.LastBagTextAtMs,o.BagTextConfidence,o.AudioReady};var command=c==null?null:new OperationCommand{Action=c.Action==FishingAction.Key?OperationAction.Key:OperationAction.None,Purpose=OperationPurpose.Farm,Key=c.Key,HoldMilliseconds=c.HoldMilliseconds,ExpectedTargetToken=c.ExpectedTargetToken,ExpectedNameHash=c.ExpectedNameHash,Reason="Fishing "+c.Purpose+": "+c.Reason};journal.Record("Fishing/"+status,new JavaScriptSerializer().Serialize(details),o.Game,command,virtualMs);if(status!=lastState){Record(status+" · "+(c==null?"":c.Reason));if(status=="Stopped"||status=="ReturnNpc"||status=="VendorWait")TakeSnapshot(status);lastState=status;}}
        void TakeSnapshot(string why){if(journal==null)return;try{if(simulation!=null){using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(Point.Empty,Size));journal.SaveSnapshot(bitmap,"simulation_owned_form: "+why);}}else if(gameCapture!=null)using(var bitmap=gameCapture())journal.SaveSnapshot(bitmap,"game_client: "+why);}catch(Exception ex){Record("本次截图不可用："+ex.Message);}}
        void SaveCheckpoint(){if(session==null||session.CurrentCheckpoint==null)return;FishingCheckpointStore.Save(Path.Combine(UserDirectory(),"last-checkpoint.json"),session.CurrentCheckpoint);}
        public void StopWorkspace(string why){runClock.Stop();pendingPlan=null;hotkeyStart=false;simTimer.Stop();if(simulation!=null&&!simulation.Completed)simulation.Engine.Stop(why);var s=session;if(s!=null){s.Stop(why);lastSessionStop=clock.ElapsedMilliseconds;stopHandled=true;try{SaveCheckpoint();}catch(Exception ex){Record("断点未保存："+ex.Message);}}if(isRecording){isRecording=false;recording=null;Record("未完成的路线录制已取消。");}StopListening();if(!closing){state.Text=why;RefreshHotkeys();}}
        public void Export(){if(runPlan==null||journal==null)throw new InvalidOperationException("请先运行一次钓鱼模拟或实机会话。");string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"reports","fishing-"+DateTime.Now.ToString("yyyyMMdd-HHmmssfff"));Directory.CreateDirectory(path);TakeSnapshot("导出记录");journal.Export(path);string[] log;lock(eventGate)log=events.ToArray();var report=new{schema_version=1,tool_version="0.7.2",report_kind="fishing",run_id=journal.RunId,source=simulation==null?"live_attempt":"offline_simulation",game_validation="pending",created_at=DateTimeOffset.Now.ToString("o"),wall_elapsed_ms=runClock.ElapsedMilliseconds,plan_fingerprint=runPlan.Fingerprint(),client_version=lastObservation==null?"":lastObservation.Game.ClientVersion,virtual_elapsed_ms=simulation==null?(object)null:simulation.ElapsedMilliseconds,native_input_events=simulation==null?(object)null:0,status=simulation!=null?simulation.Engine.Status:session==null?"Stopped":session.EngineStatus,reason=simulation!=null?simulation.Engine.LastReason:session==null?"":session.LastReason,casts=simulation!=null?simulation.Engine.Casts:session==null?0:session.Casts,reels=simulation!=null?simulation.Engine.Reels:session==null?0:session.Reels,confirmed_catches=simulation!=null?simulation.Engine.ConfirmedCatches:session==null?0:session.ConfirmedCatches,vendor_visits=simulation!=null?simulation.Engine.VendorVisits:session==null?0:session.VendorVisits,events=log};File.WriteAllText(Path.Combine(path,"fishing-report.json"),new JavaScriptSerializer{MaxJsonLength=8*1024*1024}.Serialize(report),new UTF8Encoding(true));FishingPlanStore.Save(Path.Combine(path,"fishing-plan.json"),runPlan);lastReport=path;Record("钓鱼记录已导出："+path);state.Text="记录已导出；实际游戏验收仍为pending。";}
        [DllImport("user32.dll")]static extern bool RegisterHotKey(IntPtr window,int id,uint modifiers,uint key);[DllImport("user32.dll")]static extern bool UnregisterHotKey(IntPtr window,int id);
        void UnregisterKeys(){if(!IsHandleCreated)return;foreach(int id in registeredIds)UnregisterHotKey(Handle,id);registeredIds.Clear();registered=configKeys=false;}
        void RefreshHotkeys(){if(!IsHandleCreated||closing)return;bool active=hotkeys.Checked&&Visible;bool config=active&&!SimulationRunning&&pendingPlan==null&&(session==null||!session.IsActive);if(registered==active&&configKeys==config)return;UnregisterKeys();if(!active)return;if(!RegisterHotKey(Handle,900,0x4002,0x7B)){Record("Ctrl+F12 被其他程序占用，快捷键未启用。");return;}registeredIds.Add(900);registered=true;configKeys=config;if(config)for(int i=0;i<7;i++){int id=910+i;if(RegisterHotKey(Handle,id,0x4000,(uint)(0x74+i)))registeredIds.Add(id);else Record("配置快捷键 F"+(5+i)+" 被占用。");}}
        protected override void WndProc(ref Message m){if(m.Msg==0x0312){try{int id=m.WParam.ToInt32();if(id==900){if(Busy||session!=null&&(!stopHandled||clock.ElapsedMilliseconds-lastSessionStop<1000))StopWorkspace("Ctrl+F12 暂停钓鱼。");else hotkeyStart=true;}else if(!SimulationRunning&&pendingPlan==null&&(session==null||!session.IsActive)){switch(id){case 910:SaveSpot();break;case 911:BeginRecording();break;case 912:AddPoint();break;case 913:EndRecording();break;case 914:SaveRoute();break;case 915:LoadRoute();break;case 916:SaveNpc();break;}}}catch(Exception ex){Record("快捷键未执行："+ex.Message);state.Text=ex.Message;}}base.WndProc(ref m);}
    }
